@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{color-scheme:dark;--cyan:#5af8ff;--yellow:#ffe679;--white:#f5f6fa;--muted:#75808c;--mono:'Space Mono','DM Mono',monospace;--display:'Syne','Space Grotesk',sans-serif}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#05070b;color:var(--white);font-family:var(--mono)}body{overscroll-behavior:none}button{font:inherit}#app{position:relative;width:100%;height:100%;min-height:500px;overflow:hidden;background:radial-gradient(ellipse at 75% 47%,#12202a 0,#091017 33%,#05070b 72%);isolation:isolate}#world,#flames{position:absolute;inset:0;width:100%;height:100%;display:block}#world{z-index:0}#flames{z-index:1;pointer-events:none;opacity:.82;transition:opacity 1s}#app.battle #flames{opacity:.08}.vignette,.noise{position:absolute;inset:0;pointer-events:none}.vignette{z-index:2;background:radial-gradient(ellipse at 50% 45%,transparent 35%,rgba(0,0,0,.24) 77%,rgba(0,0,0,.7) 130%)}.noise{z-index:3;opacity:.1;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.22'/%3E%3C/svg%3E");mix-blend-mode:screen}.hud{position:absolute;z-index:5;left:clamp(20px,4vw,58px);right:clamp(20px,4vw,58px);top:clamp(18px,3.8vh,38px);display:flex;justify-content:space-between;align-items:center;font-size:9px;letter-spacing:.18em;color:#a6b0bd}.brand-mark{display:flex;align-items:center;gap:10px}.brand-dot{width:7px;height:7px;border-radius:50%;background:var(--cyan);box-shadow:0 0 12px var(--cyan)}.sound-toggle{display:flex;align-items:center;gap:9px;cursor:pointer;user-select:none;transition:color .2s}.sound-toggle:hover{color:white}.sound-bars{height:13px;display:flex;align-items:center;gap:2px}.sound-bars i{display:block;width:2px;height:4px;background:var(--cyan);border-radius:2px}.sound-bars i:nth-child(2