eyframes fadeUp{to{opacity:1;transform:translateY(0)}}.intro-caption{position:absolute;z-index:4;left:clamp(26px,9vw,140px);top:clamp(360px,65vh,635px);display:flex;align-items:center;gap:13px;font-size:8px;letter-spacing:.16em;color:#72818a;opacity:0;animation:fadeUp .8s 2.4s forwards}.caption-line{display:inline-block;width:25px;height:1px;background:var(--cyan);box-shadow:0 0 8px var(--cyan)}.bottom-meta{position:absolute;z-index:4;left:clamp(20px,4vw,58px);right:clamp(20px,4vw,58px);bottom:clamp(18px,3.5vh,32px);display:flex;justify-content:space-between;font-size:8px;letter-spacing:.16em;color:#66737c;transition:opacity .4s}.ready-button{position:absolute;z-index:6;left:50%;bottom:clamp(42px,8vh,76px);width:min(252px,70vw);height:57px;transform:translate(-50%,35px);background:#030609;border:1px solid rgba(255,255,255,.85);color:white;display:flex;align-items:center;justify-content:center;gap:32px;letter-spacing:.34em;font-size:12px;cursor:pointer;opacity:0;pointer-events:none;box-shadow:0 0 0 1px rgba(90,248,255,.1),0 0 30px rgba(0,220,255,.09);transition:background .25s,color .25s,box-shadow .25s,transform .25s}.ready-button:before{content:'';position:absolute;inset:4px;border:1px solid rgba(255,255,255,.12);pointer-events:none}.ready-button b{font-size:17px;font-weight:400;color:var(--cyan);transition:transform .2s}.ready-button:hover{background:#eaffff;color:#05070b;box-shadow:0 0 28px rgba(90,248,255,.4)}.ready-button:hover b{transform:translateX(5px);color:#05070b}.ready-button.show{pointer-events:auto;animation:buttonRise .8s 0s cubic-bezier(.16,1,.3,1) forwards}@keyframes buttonRise{to{opacity:1;transform:translate(-50%,0)}}.battle-hud{position:absolute;inset:0;z-index:6;display:none;pointer-events:none}.battle-hud>*{pointer-events:auto}.battle-hud.active{display:block}.battle-topline{position:absolute;top:clamp(68px,10vh,105px);left:50%;transform:translateX(-50%);width:min(440px,74vw);display:flex;justify-content:space-between;align-items:end;text-align:center}.battle-topline>div{display:grid;gap:5px}.battle-topline strong{font-family:var(--display);font-size:18px;letter-spacing:.19em}.tiny-label{font-size:8px;letter-spacing:.22em;color:#7e8d97}.wave-readout strong{color:var(--cyan)}.boss-bar{position:absolute;top:clamp(126px,17vh,168px);left:50%;transform:translateX(-50%);width:min(420px,70vw);height:3px;background:#1d2730}.boss-bar span{display:block;width:100%;height:100%;background:linear-gradient(90deg,#75f9ff,#bb74ff);box-shadow:0 0 10px rgba(90,248,255,.7);transition:width .5s}.battle-status{position:absolute;top:clamp(148px,19vh,190px);left:50%;transform:translateX(-50%);width:min(430px,78vw);display:flex;justify-content:space-between;color:#cbd2d8;font-size:9px;letter-spacing:.09em}.turn-clock{color:var(--cyan)}.arena-frame{position:absolute;left:50%;top:51%;transform:translate(-50%,-50%);width:min(490px,80vw);height:min(240px,32vh);min-height:160px;border:2px solid #e8edf0;background:rgba(3,6,10,.66);box-shadow:0 0 0 1px rgba(90,248,255,.08),0 0 38px rgba(0,0,0,.55),inset 0 0 40px rgba(29,63,75,.22);overflow:hidden;touch-action:none}.arena-frame:before,.arena-frame:after{content:'';position:absolute;inset:7px;border:1px solid rgba(255,255,255,.045);pointer-events:none}.arena-glow{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 100%,rgba(0,188,221,.09),transparent 65%)}.soul{position:absolute;left:50%;top:55%;transform:translate(-50%,-50%);font-family:Arial,sans-serif;font-size:26px;line-height:1;color:#ff3b4e;text-shadow:0 0 5px #ff1d38,0 0 16px #fc2144;z-index:3;user-select:none;touch-action:none;cursor:grab;filter:drop-shadow(0 1px 5px rgba(255,0,40,.65));transition:filter .15s}.soul.hurt{animation:soulHurt .28s}@keyframes soulHurt{50%{filter:brightness(3) drop-shadow(0 0 12px red);transform:translate(-50%,-50%) scale(1.4)}}.player-stats{position:absolute;left:50%;top:calc(51% + min(120px,16vh) + 17px);transform:translateX(-50%);width:min(490px,80vw);display:grid;grid-template-columns:1fr minmax(95px,1.3fr) auto;align-items:center;gap:12px;font-size:9px}.player-name{font-family:var(--display);letter-spacing:.08em;font-weight:700}.player-name span{margin-left:8px;color:#b1bac1;font-family:var(--mono);font-size:8px}.hp-track{height:11px;background:#643c32;position:relative}.hp-track span{height:100%;width:100%;display:block;background:linear-gradient(90deg,#ffe96d,#ffb23f);transition:width .25s}.hp-numbers{font-family:var(--display);font-weight:700;font-size:13px;color:#ffe676;white-space:nowrap}.hp-numbers span{font-family:var(--mono);font-size:8px;color:#c2c8ca;margin-left:4px}.battle-actions{position:absolute;bottom:clamp(36px,7vh,65px);left:50%;transform:translateX(-50%);width:min(590px,88vw);display:flex;justify-content:space-between;gap:clamp(7px,2vw,18px)}.action-button{height:45px;flex:1;background:rgba(3,6,10,.88);border:1px solid #d5d9d9;color:#ffe36e;display:flex;justify-content:center;align-items:center;gap:8px;font-family:var(--display);font-size:12px;font-weight:700;letter-spacing:.06em;cursor:pointer;transition:all .2s}.action-button:hover,.action-button.active{border-color:#ffe36e;color:#fff4b1;box-shadow:0 0 15px rgba(255,226,88,.13);transform:translateY(-2px)}.action-icon{font-size:16px}.touch-hint{position:absolute;left:50%;transform:translateX(-50%);bottom:16px;color:#6f7b84;font-size:7px;letter-spacing:.13em;white-space:nowrap}.touch-hint kbd{font-family:var(--mono);font-size:7px;color:#aab7bf;border:1px solid #38434b;padding:2px 3px;border-radius:2px;margin:0 2px}.restart-button{display:none;position:absolute;left:50%;top:calc(51% + 15px);transform:translate(-50%,-50%);padding:14px 22px;background:#05090c;border:1px solid var(--cyan);color:var(--cyan);font-size:10px;letter-spacing:.15em;cursor:pointer;box-shadow:0 0 20px #00d9ff30}.battle-hud.over .restart-button{display:block}.battle-hud.over .arena-frame{border-color:#ff7182}.toast{position:absolute;z-index:8;left:50%;top:38%;transform:translate(-50%,10px);padding:11px 16px;background:rgba(2,7,10,.92);border:1px solid rgba(90,248,255,.4);font-size:9px;letter-spacing:.08em;color:#d7faff;opacity:0;transition:.3s;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.screen-flash{position:absolute;z-index:7;inset:0;background:#fff;opacity:0;pointer-events:none}.screen-flash.hit{animation:flash .2s}@keyframes flash{50%{opacity:.25}}#app.battle .title-stack,#app.battle .intro-caption,#app.battle .bottom-meta,#app.battle .ready-button{opacity:0;pointer-events:none;transition:opacity .5s}.battle-hud{opacity:0;transition:opacity .5s}.battle-hud.active{opacity:1}.battle-hud.over .battle-actions,.battle-hud.over .touch-hint{opacity:.3;pointer-events:none}
